import os, json
ROOT = r'D:/repository'
SKIP = {'node_modules', '.git', 'dist', 'build', '.cache', '.vn', 'coverage'}
EXTS = ('.vue','.js','.ts','.jsx','.tsx','.py','.json','.scss','.css','.md','.njk','.html','.svg','.yml','.yaml')
ARCH = ('skills/memory-migration-archive','skills/openviking-data','skills/openviking-memory')

# idx: (dirs[list of abs/rel-to-ROOT], patterns, logic)
C = {
 3:  (['苏州市房地产监测V3'], ['syncSelectedHouseHighlight','handleClickNode','selectedHouse'], 'any'),
 7:  (['门户'], ['platform_banner_desc_line1','platform-banner-desc-enter-mobile','platform_banner_desc_line2'], 'any'),
