 15: (['苏住房C'], ['appSuggestListVoList','complexId'], 'all'),
 21: (['苏州市房地产监测V3'], ['market-monitor.standalone','mm-dashboard'], 'any'),
 24: (['苏住房C'], ['httpInstance','gateway'], 'any'),
 25: (['产品2.0'], ['buildApiRequestHeaders','Admin-Token'], 'any'),
 29: (['产品2.0'], ['updateCompanyRecordChange','companyRecord'], 'any'),
 30: (['园区物管2.0'], ['STAT_ICON_MAP','statIconStyle','净水机'], 'any'),
 32: (['苏州市房地产监测V3','苏住房G','产品2.0'], ['supervisionBankBranchName','supervisionBank'], 'any'),
 39: (['苏住房防汛C端','查询H5'], ['callPhone','立即受理','detail.vue'], 'any'),
 40: (['苏住房防汛C端'], ['theme.css','flows.spec.ts','pixelmatch'], 'any'),
 41: (['skills'], ['maxAttrLoops','Date.now'], 'any'),
 43: (['i淮安H5'], ['echarts-uniapp','legend','38%'], 'any'),
 44: (['苏住房C'], ['conditionScreening','reset.svg','footer-btn-left'], 'any'),
 45: (['苏住房防汛C端'], ['REF_MAIN_HTML','ref-assets','terminalType'], 'any'),
}

def scan(base, pats, seen):
    if not os.path.isdir(base): return
    for dp, dns, fns in os.walk(base):
        dns[:] = [d for d in dns if d not in SKIP and not d.startswith('.')]
        for fn in fns:
            if not fn.endswith(EXTS): continue
            fp = os.path.join(dp, fn)
            try: txt = open(fp,'r',encoding='utf-8',errors='ignore').read()
            except Exception: continue
            rel = os.path.relpath(fp, ROOT).replace('\\','/')
            if rel.startswith(ARCH): continue
            for p in pats:
                if p in txt and len(seen[p]) < 4:
                    seen[p].append(rel)

out = {}
for idx,(dirs,pats,logic) in C.items():
    seen = {p:[] for p in pats}
    for d in dirs:
        base = os.path.join(ROOT,d)
        scan(base, pats, seen)
    ok = all(seen[p] for p in pats) if logic=='all' else any(seen[p] for p in pats)
    out[idx] = {'ok':ok,'detail':seen}

# #42 Cursor config outside ROOT
c42 = {'shouldBlockMcp':[], 'workbench.mcp.allowlist':[], 'tdai_recall':[]}
for base in [r'C:/Users/Administrator/.cursor', r'C:/Users/Administrator/AppData/Roaming/Cursor']:
    for dp,dns,fns in os.walk(base):
        dns[:] = [d for d in dns if d not in SKIP]
        for fn in fns:
            if not fn.endswith(('.json','.log','.md','.js','.ts')): continue
            fp=os.path.join(dp,fn)
            try: txt=open(fp,'r',encoding='utf-8',errors='ignore').read()
            except Exception: continue
            for p in c42:
                if p in txt and len(c42[p])<4: c42[p].append(os.path.relpath(fp,base).replace('\\','/'))
out[42]={'ok':any(c42[p] for p in c42),'detail':c42}

json.dump(out, open(r'C:/Users/Administrator/.dsh/cache/memory-audit/verify3_result.json','w',encoding='utf-8'), ensure_ascii=False)
lines=[]
for idx in sorted(out):
    o=out[idx]
    hits=[f"{p}={o['detail'][p][:2]}" for p in o['detail'] if o['detail'][p]]
    lines.append(f"{idx:>2} {'OK' if o['ok'] else 'FAIL'} | "+' ; '.join(hits))
open(r'C:/Users/Administrator/.dsh/cache/memory-audit/verify3_view.txt','w',encoding='utf-8').write('\n'.join(lines))
print('done')

